import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Placeholder Reference","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/cooking/placeholders.md","filePath":"en/modules/cooking/placeholders.md","lastUpdated":0}`),a={name:`en/modules/cooking/placeholders.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="placeholder-reference" tabindex="-1">Placeholder Reference <a class="header-anchor" href="#placeholder-reference" aria-label="Permalink to “Placeholder Reference”">​</a></h1><h2 id="placeholderapi-placeholders" tabindex="-1">PlaceholderAPI Placeholders <a class="header-anchor" href="#placeholderapi-placeholders" aria-label="Permalink to “PlaceholderAPI Placeholders”">​</a></h2><p>Expansion identifier: <code>emakicooking</code></p><p>When PlaceholderAPI is installed, EmakiCooking registers the following placeholders.</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>%emakicooking_recipe_count%</code></td><td>Total recipe count across all stations.</td><td><code>42</code></td></tr><tr><td><code>%emakicooking_recipe_count_chopping_board%</code></td><td>Chopping board recipe count.</td><td><code>8</code></td></tr><tr><td><code>%emakicooking_recipe_count_wok%</code></td><td>Wok recipe count.</td><td><code>12</code></td></tr><tr><td><code>%emakicooking_recipe_count_grinder%</code></td><td>Grinder recipe count.</td><td><code>5</code></td></tr><tr><td><code>%emakicooking_recipe_count_steamer%</code></td><td>Steamer recipe count.</td><td><code>6</code></td></tr><tr><td><code>%emakicooking_recipe_count_oven%</code></td><td>Oven recipe count.</td><td><code>4</code></td></tr><tr><td><code>%emakicooking_recipe_count_juicer%</code></td><td>Juicer recipe count.</td><td><code>3</code></td></tr><tr><td><code>%emakicooking_recipe_count_fermentation_barrel%</code></td><td>Fermentation barrel recipe count.</td><td><code>4</code></td></tr></tbody></table><h3 id="nutrition-placeholders" tabindex="-1">Nutrition placeholders <a class="header-anchor" href="#nutrition-placeholders" aria-label="Permalink to “Nutrition placeholders”">​</a></h3><p>Nutrition placeholders also use the <code>emakicooking</code> identifier. See <a href="./nutrition.html">Nutrition System</a> for the gameplay.</p><table tabindex="0"><thead><tr><th>Placeholder</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>%emakicooking_nutrition_&lt;type&gt;%</code></td><td>Current value of a player&#39;s nutrition type.</td><td><code>60</code></td></tr><tr><td><code>%emakicooking_nutrition_&lt;type&gt;_max%</code></td><td>Upper bound of a nutrition type.</td><td><code>100</code></td></tr><tr><td><code>%emakicooking_nutrition_&lt;type&gt;_min%</code></td><td>Lower bound of a nutrition type.</td><td><code>0</code></td></tr><tr><td><code>%emakicooking_nutrition_combo_count_&lt;ruleId&gt;%</code></td><td>Number of nutrition types currently qualifying for a combo threshold rule.</td><td><code>3</code></td></tr></tbody></table><p><code>&lt;type&gt;</code> is a nutrition type id (such as <code>fruit</code> or <code>protein</code>), and <code>&lt;ruleId&gt;</code> is a combo threshold rule id. Nutrition placeholders depend on player state and require an online player context.</p><h3 id="station-runtime-placeholders" tabindex="-1">Station Runtime Placeholders <a class="header-anchor" href="#station-runtime-placeholders" aria-label="Permalink to “Station Runtime Placeholders”">​</a></h3><p>Station runtime placeholders read the live state of the player&#39;s currently associated station, also using the <code>emakicooking</code> identifier. There are two forms:</p><ul><li><code>%emakicooking_station_&lt;field&gt;%</code>: automatically uses the player&#39;s currently associated station.</li><li><code>%emakicooking_station_&lt;type&gt;_&lt;field&gt;%</code>: only returns a value when the player&#39;s associated station matches the given type, otherwise an empty string. The type is a folder name (<code>chopping_board</code>, <code>wok</code>, <code>grinder</code>, <code>steamer</code>, <code>oven</code>, <code>juicer</code>, <code>fermentation_barrel</code>).</li></ul><p>Association order: the player&#39;s <strong>most recently used station</strong> first (the player must still be in the same world and within a built-in distance limit), then the station GUI session the player currently has open (steamer / oven / juicer / fermentation barrel). Returns an empty string when the player has no associated station or the station is empty.</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>type</code></td><td>Station type (folder name).</td><td><code>chopping_board</code></td></tr><tr><td><code>type_name</code></td><td>Station display name.</td><td><code>Chopping Board</code></td></tr><tr><td><code>world</code></td><td>Station world name.</td><td><code>world</code></td></tr><tr><td><code>x</code></td><td>Station block X coordinate.</td><td><code>100</code></td></tr><tr><td><code>y</code></td><td>Station block Y coordinate.</td><td><code>64</code></td></tr><tr><td><code>z</code></td><td>Station block Z coordinate.</td><td><code>-200</code></td></tr><tr><td><code>location</code></td><td>Combined coordinate string <code>world,x,y,z</code> for whole-string matching.</td><td><code>world,100,64,-200</code></td></tr><tr><td><code>block</code></td><td>Station block id (custom block id or vanilla Material name).</td><td><code>minecraft:oak_log</code></td></tr><tr><td><code>heat_block</code></td><td>Heat source block id (below the station; empty when none).</td><td><code>minecraft:furnace</code></td></tr><tr><td><code>burning</code></td><td>Whether the heat source is burning.</td><td><code>true</code></td></tr><tr><td><code>burning_seconds</code></td><td>Remaining burn seconds of the heat source.</td><td><code>40</code></td></tr><tr><td><code>heat</code></td><td>Heat (oven) / heat level (wok).</td><td><code>60</code></td></tr><tr><td><code>moisture</code></td><td>Moisture (steamer).</td><td><code>80</code></td></tr><tr><td><code>steam</code></td><td>Steam (steamer).</td><td><code>30</code></td></tr><tr><td><code>input</code></td><td>Plain text name of the main input item.</td><td><code>Apple</code></td></tr><tr><td><code>input_source</code></td><td>Main input item source shorthand.</td><td><code>minecraft-apple</code></td></tr><tr><td><code>input_amount</code></td><td>Main input item amount.</td><td><code>16</code></td></tr><tr><td><code>ingredient_count</code></td><td>Number of input item types.</td><td><code>3</code></td></tr><tr><td><code>recipe</code></td><td>Display name of the matched / in-progress recipe.</td><td><code>Apple Juice</code></td></tr><tr><td><code>recipe_id</code></td><td>Current recipe id.</td><td><code>apple_juice</code></td></tr><tr><td><code>progress</code></td><td>Current progress value.</td><td><code>2</code></td></tr><tr><td><code>progress_target</code></td><td>Target progress value.</td><td><code>5</code></td></tr><tr><td><code>progress_percent</code></td><td>Progress percentage (one decimal place).</td><td><code>40.0</code></td></tr><tr><td><code>completed</code></td><td>Whether it is completed (collectable).</td><td><code>false</code></td></tr><tr><td><code>fluid</code></td><td>Fluid name (juicer).</td><td><code>Apple Juice</code></td></tr><tr><td><code>fluid_amount</code></td><td>Fluid amount in ml (juicer).</td><td><code>500</code></td></tr><tr><td><code>player</code></td><td>Operating / viewing player name.</td><td><code>Steve</code></td></tr></tbody></table><p>Fields that do not apply to the current station return an empty string or 0 (for example a chopping board has no heat source, so <code>heat_block</code> is empty and <code>burning</code> is <code>false</code>).</p><h4 id="condition-recipe-gameplay-example" tabindex="-1">Condition Recipe Gameplay Example <a class="header-anchor" href="#condition-recipe-gameplay-example" aria-label="Permalink to “Condition Recipe Gameplay Example”">​</a></h4><p>Combined with a recipe&#39;s <code>availability_condition</code> / <code>condition</code>, station coordinates can distinguish specific stations of the same type. For example, place two identical chopping boards and let only the one at a specific coordinate complete a recipe (the combined coordinate string contains commas, so quote it for string comparison):</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">availability_condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">all_of</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  entries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%emakicooking_station_location% == &quot;world,100,64,-200&quot;&#39;</span></span></code></pre></div><p>You can also match a single coordinate field:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">availability_condition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">all_of</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  entries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%emakicooking_station_x% == 100&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;%emakicooking_station_z% == -200&#39;</span></span></code></pre></div><p>See <a href="./../corelib/condition.html">Condition System</a> for the full condition block syntax (<code>type</code> / <code>entries</code> / <code>on_fail</code>, etc.).</p><h3 id="usage-example" tabindex="-1">Usage Example <a class="header-anchor" href="#usage-example" aria-label="Permalink to “Usage Example”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;Total recipes: &lt;white&gt;%emakicooking_recipe_count%&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;Wok recipes: &lt;white&gt;%emakicooking_recipe_count_wok%&#39;</span></span></code></pre></div><h2 id="internal-template-variables" tabindex="-1">Internal Template Variables <a class="header-anchor" href="#internal-template-variables" aria-label="Permalink to “Internal Template Variables”">​</a></h2><p>The following variables are available in recipe <code>structured_presentation</code> (name and lore action templates) using the <code>%variable%</code> format.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>%recipe_id%</code></td><td>Recipe ID.</td><td><code>grilled_steak</code></td></tr><tr><td><code>%recipe_name%</code></td><td>Recipe display name.</td><td><code>Grilled Steak</code></td></tr><tr><td><code>%station_type%</code></td><td>Station type (folder name).</td><td><code>oven</code></td></tr><tr><td><code>%phase%</code></td><td>Current cooking phase.</td><td><code>cooking</code></td></tr><tr><td><code>%output_source%</code></td><td>Output item source shorthand.</td><td><code>minecraft-cooked_beef</code></td></tr><tr><td><code>%output_amount%</code></td><td>Output amount.</td><td><code>1</code></td></tr><tr><td><code>%output_chance%</code></td><td>Output chance.</td><td><code>100%</code></td></tr><tr><td><code>%output_amount_min%</code></td><td>Minimum of output amount range. Present only when the outcome declares <code>amount_range</code>.</td><td><code>1</code></td></tr><tr><td><code>%output_amount_max%</code></td><td>Maximum of output amount range. Present only when the outcome declares <code>amount_range</code>.</td><td><code>3</code></td></tr></tbody></table><p><code>%output_source%</code> uses the CoreLib ItemSource shorthand form, for example <code>minecraft-cooked_beef</code>.</p><h3 id="template-example" tabindex="-1">Template Example <a class="header-anchor" href="#template-example" aria-label="Permalink to “Template Example”">​</a></h3><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">structured_presentation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  lore_actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;append&quot;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">      content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;Recipe: &lt;white&gt;%recipe_name%&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;Station: &lt;white&gt;%station_type%&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gray&gt;Output: &lt;white&gt;%output_amount%x %output_source%&quot;</span></span></code></pre></div><h2 id="action-context-variables" tabindex="-1">Action Context Variables <a class="header-anchor" href="#action-context-variables" aria-label="Permalink to “Action Context Variables”">​</a></h2><p>When cooking reward actions (CookingRewardService) are triggered, the following variables are injected into the action context:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>%player%</code></td><td>Player name.</td><td><code>Steve</code></td></tr><tr><td><code>%player_uuid%</code></td><td>Player UUID.</td><td><code>00000000-0000-0000-0000-000000000000</code></td></tr><tr><td><code>%world%</code></td><td>World name.</td><td><code>world</code></td></tr><tr><td><code>%x%</code></td><td>Station block X coordinate.</td><td><code>100</code></td></tr><tr><td><code>%y%</code></td><td>Station block Y coordinate.</td><td><code>64</code></td></tr><tr><td><code>%z%</code></td><td>Station block Z coordinate.</td><td><code>-200</code></td></tr><tr><td><code>%recipe_id%</code></td><td>Current recipe ID.</td><td><code>grilled_steak</code></td></tr><tr><td><code>%recipe_name%</code></td><td>Recipe display name.</td><td><code>Grilled Steak</code></td></tr><tr><td><code>%station_type%</code></td><td>Station type (folder name).</td><td><code>oven</code></td></tr><tr><td><code>%cooking_recipe_id%</code></td><td>Prefixed form of <code>%recipe_id%</code>.</td><td><code>grilled_steak</code></td></tr><tr><td><code>%cooking_recipe_name%</code></td><td>Prefixed form of <code>%recipe_name%</code>.</td><td><code>Grilled Steak</code></td></tr><tr><td><code>%cooking_station_type%</code></td><td>Prefixed form of <code>%station_type%</code>.</td><td><code>oven</code></td></tr><tr><td><code>%input_count%</code></td><td>Number of input ingredient entries in this settlement.</td><td><code>3</code></td></tr></tbody></table><p>Some stations inject additional variables when they settle a result:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Injected by</th><th>Description</th></tr></thead><tbody><tr><td><code>%outcome%</code></td><td>Wok</td><td>The matched outcome branch name.</td></tr><tr><td><code>%slot_index%</code></td><td>Oven, steamer, juicer</td><td>The slot index being settled.</td></tr></tbody></table><p>Output-level templates (<code>structured_presentation</code>) additionally receive <code>%phase%</code>, <code>%output_source%</code>, <code>%output_amount%</code>, <code>%output_chance%</code>, <code>%output_amount_min%</code>, and <code>%output_amount_max%</code>.</p><h3 id="action-example" tabindex="-1">Action Example <a class="header-anchor" href="#action-example" aria-label="Permalink to “Action Example”">​</a></h3><p>Recipe outcome <code>actions</code> are CoreLib action strings:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send_message text=&quot;&lt;green&gt;%player% finished cooking %recipe_id% at the %station_type%!&lt;/green&gt;&quot;&#39;</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>PAPI placeholders do not depend on player state for the <code>recipe_count</code> series, which are global values suitable for admin panels or scoreboards. Nutrition placeholders require an online player context.</li><li>CoreLib built-in context variables (<code>%player_name%</code>, <code>%player_uuid%</code>, etc.) are also available.</li></ul>`,40)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};